package ru.neverland.townycitizens;
import java.util.*;
import java.util.concurrent.CompletionStage;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import com.palmergames.bukkit.towny.TownyAPI;
import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.SuiteState;
import ru.neverland.townycitizens.model.*;
import static ru.neverland.townycitizens.model.Admissions.*;

public final class AdmissionsService {
    private final NeverLandTownyCitizens plugin;private final CitizensService citizens;
    public AdmissionsService(NeverLandTownyCitizens plugin,CitizensService citizens){this.plugin=plugin;this.citizens=citizens;}
    public boolean enabled(){return plugin.getConfig().getBoolean("applications.enabled",true);}
    public State state(){return citizens.repository().state();}
    public Terms terms(UUID town){return state().board().terms(town);}
    private void active(){if(!SuiteState.held())throw new IllegalStateException("Нужна согласованная операция гражданства");if(!enabled()||!plugin.isEnabled()||SuiteState.frozen(plugin.getName()))throw new IllegalArgumentException("Заявления сейчас приостановлены; текущие статусы сохранены");}
    private void use(Player p){active();if(!p.hasPermission("neverlandtownycitizens.use"))throw new IllegalArgumentException("Нет права просмотра гражданства");}
    public boolean sponsorEligible(UUID resident,UUID town){var own=citizens.ownTown(resident);if(own==null||!own.getUUID().equals(town))return false;var status=citizens.effective(town,resident);return status==CitizenshipStatus.CITIZEN||status==CitizenshipStatus.HONORARY;}
    public boolean visible(Player p,Application a){return a.applicant().equals(p.getUniqueId())||a.sponsors().containsKey(p.getUniqueId())||citizens.manages(p,TownyAPI.getInstance().getTown(a.town()))||sponsorEligible(p.getUniqueId(),a.town());}
    public Application application(Player p,UUID id){use(p);var a=state().board().applications().get(id);if(a==null||!visible(p,a))throw new IllegalArgumentException("Заявление не найдено или недоступно");return a;}
    public List<Application> list(Player p,UUID town){use(p);return state().board().applications().values().stream().filter(a->(town==null||town.equals(a.town()))&&visible(p,a)).sorted(Comparator.comparingLong(Application::created).reversed()).toList();}
    public Set<UUID> eligible(Application a){var result=new HashSet<UUID>();for(UUID id:a.sponsors().keySet())if(sponsorEligible(id,a.town()))result.add(id);return Set.copyOf(result);}
    public List<String> blockers(Application a){var r=TownyAPI.getInstance().getResident(a.applicant());var town=TownyAPI.getInstance().getTown(a.town());return Admissions.blockers(a,eligible(a),r!=null,r!=null&&town!=null&&town.equals(r.getTownOrNull()),town!=null&&town.getMayor()!=null&&town.getMayor().getUUID().equals(a.applicant()),System.currentTimeMillis());}
    public Application proposal(Player p,Town town,CitizenshipStatus status,int days,String message){use(p);if(!p.hasPermission("neverlandtownycitizens.apply"))throw new IllegalArgumentException("Нет права подавать заявления");if(town==null)throw new IllegalArgumentException("Город не найден");var resident=TownyAPI.getInstance().getResident(p);if(resident==null)throw new IllegalArgumentException("Игрок не зарегистрирован в Towny");if(state().board().applications().values().stream().anyMatch(a->a.phase()==Phase.OPEN&&a.town().equals(town.getUUID())&&a.applicant().equals(p.getUniqueId())))throw new IllegalArgumentException("В этом городе у вас уже есть открытое заявление");return new Application(UUID.randomUUID(),town.getUUID(),p.getUniqueId(),p.getName(),status,days,citizens.settings().maximumTemporaryDays(),terms(town.getUUID()),Math.max(0,resident.getRegistered()),message,System.currentTimeMillis(),Phase.OPEN,Map.of(),null,"",0,"",1);}
    public CompletionStage<State> submit(Player p,Application quoted){use(p);if(!p.hasPermission("neverlandtownycitizens.apply")||!quoted.applicant().equals(p.getUniqueId())||TownyAPI.getInstance().getTown(quoted.town())==null||TownyAPI.getInstance().getResident(p)==null||citizens.settings().maximumTemporaryDays()!=quoted.maximumDays())throw new IllegalArgumentException("Условия подачи изменились");var before=state();return citizens.persist(p,quoted.town(),before,Admissions.submit(before,quoted),"CITIZEN_APPLICATION","Подано заявление "+quoted.id()+"; статус "+quoted.desired());}
    public CompletionStage<State> support(Player p,UUID id,long revision,boolean remove){var a=application(p,id);if(!remove&&(!p.hasPermission("neverlandtownycitizens.sponsor")||!sponsorEligible(p.getUniqueId(),a.town())))throw new IllegalArgumentException("Поручиться может действующий гражданин этого города");var before=state();var next=Admissions.sponsor(before,id,revision,new Sponsor(p.getUniqueId(),p.getName(),System.currentTimeMillis()),remove);return citizens.persist(p,a.town(),before,next,"CITIZEN_APPLICATION",(remove?"Отозвано поручительство ":"Поручительство ")+id);}
    public CompletionStage<State> decide(Player p,UUID id,long revision,Phase phase,String reason){var a=application(p,id);var town=TownyAPI.getInstance().getTown(a.town());if(phase!=Phase.WITHDRAWN&&(town==null||!citizens.manages(p,town)))throw new IllegalArgumentException("Решение принимает мэр этого города или администратор");var resident=TownyAPI.getInstance().getResident(a.applicant());var before=state();var next=Admissions.decide(before,id,revision,phase,p.getUniqueId(),p.getName(),reason,System.currentTimeMillis(),eligible(a),resident!=null,resident!=null&&town!=null&&town.equals(resident.getTownOrNull()),town!=null&&town.getMayor()!=null&&town.getMayor().getUUID().equals(a.applicant()));return citizens.persist(p,a.town(),before,next,"CITIZEN_APPLICATION","Заявление "+id+" → "+phase+"; статус "+a.desired()+"; "+reason);}
    public CompletionStage<State> policy(Player p,UUID id,Terms next,long expected){use(p);var town=TownyAPI.getInstance().getTown(id);if(town==null||!citizens.manages(p,town))throw new IllegalArgumentException("Условия меняет мэр своего города или администратор");var before=state();return citizens.persist(p,id,before,Admissions.policy(before,id,next,expected),"CITIZEN_RULES","Новые условия для будущих заявлений: поручители "+next.sponsors()+"; дней на сервере "+next.minimumDays()+"; "+next.text());}
}
